// @juju/react-native/metro: gives each React Native bundle a debug id, so
// juju finds the source map made by the same build, whatever the release
// is called.
//
//   // metro.config.js
//   const { withJujuConfig } = require("@juju/react-native/metro");
//   module.exports = withJujuConfig(mergeConfig(getDefaultConfig(__dirname), config));
//
// Release builds compile the bundle to Hermes bytecode, so nothing can be
// added to it afterwards, the way `juju sourcemaps inject` does on the web.
// Instead, a tiny generated file joins the bundle as a polyfill (code Metro
// runs before any module). It records the id at run time, for the SDK to
// send with each error. Its source, id included, also ends up in the final
// source map the build writes, which is how the server reads the id when
// the map is uploaded. Nothing else to run, before or after the build.
"use strict";

const crypto = require("crypto");
const fs = require("fs");
const path = require("path");

// Must stay identical to Snippet() in server/internal/debugid: the server
// recognizes it in uploaded maps (a test checks both against one file).
function snippet(id) {
  return `;!function(){try{var g="undefined"!=typeof globalThis?globalThis:"undefined"!=typeof window?window:"undefined"!=typeof self?self:{},s=(new Error).stack;s&&((g.__jujuDebugIds=g.__jujuDebugIds||{})[s]="${id}")}catch(e){}}();`;
}

const DAY = 24 * 60 * 60 * 1000;

/**
 * Wraps a Metro config so every bundle it makes carries a new debug id.
 * @template T
 * @param {T} config a Metro config, e.g. mergeConfig(getDefaultConfig(__dirname), {...})
 * @returns {T}
 */
function withJujuConfig(config) {
  const cfg = /** @type {any} */ (config) || {};
  // Inside the project: Metro only bundles files it watches.
  const dir = path.join(cfg.projectRoot || process.cwd(), "node_modules", ".cache", "juju");
  fs.mkdirSync(dir, { recursive: true });
  removeOld(dir);

  // A new id, in a file of its own, for every Metro process: Android and
  // iOS builds running at once can't end up sharing one id.
  const id = crypto.randomUUID();
  const file = path.join(dir, `debug-id-${process.pid}-${Date.now()}.js`);
  fs.writeFileSync(file, `// Generated by @juju/react-native/metro: this bundle's debug id.\n${snippet(id)}\n`);

  const serializer = cfg.serializer || {};
  const getPolyfills = serializer.getPolyfills;
  return {
    ...cfg,
    serializer: {
      ...serializer,
      getPolyfills: (options) => [...(getPolyfills ? getPolyfills(options) : []), file],
    },
  };
}

// Each build leaves one small file behind; keep a day's worth.
function removeOld(dir) {
  for (const name of fs.readdirSync(dir)) {
    if (!name.startsWith("debug-id-")) continue;
    const p = path.join(dir, name);
    try {
      if (Date.now() - fs.statSync(p).mtimeMs > DAY) fs.unlinkSync(p);
    } catch {
      // another build removed it first
    }
  }
}

module.exports = { withJujuConfig, snippet };
